css.content:
/* Slider and toggle on Radix. */
.slider { position: relative; display: flex; align-items: center; width: 100%; height: 20px; touch-action: none; user-select: none; }
.slider-track { position: relative; flex: 1; height: 2px; background: var(--rule); }
.slider-range { position: absolute; height: 100%; background: var(--foreground); }
.slider-thumb { display: block; width: 14px; height: 14px; background: var(--foreground); border: 0; cursor: grab; }
.slider[data-disabled] { opacity: 0.5; }
.toggle { padding: var(--s2) var(--s4); border: 1px solid var(--rule); color: var(--muted); font-size: var(--text-sm); }
.toggle:hover:not(:disabled) { color: var(--foreground); border-color: var(--foreground); }
.toggle[data-state="on"] { background: var(--foreground); color: var(--background); border-color: var(--foreground); }
.toggle:disabled { opacity: 0.5; cursor: not-allowed; }
.toggle-group { display: inline-flex; gap: var(--s2); }

/* ─── Range, progress, meter ─── */
.range { appearance: none; width: 100%; height: 20px; background: transparent; cursor: pointer; }
.range::-webkit-slider-runnable-track { height: 2px; background: var(--foreground); }
.range::-moz-range-track { height: 2px; background: var(--foreground); }
.range::-webkit-slider-thumb { appearance: none; width: 14px; height: 14px; margin-top: -6px; background: var(--foreground); border: 0; border-radius: var(--radius); }
.range::-moz-range-thumb { width: 14px; height: 14px; background: var(--foreground); border: 0; border-radius: var(--radius); }
.range:disabled { opacity: 0.5; cursor: not-allowed; }
.progress { appearance: none; display: block; width: 100%; height: 8px; border: 1px solid var(--foreground); background: transparent; border-radius: var(--radius); overflow: hidden; }
.progress::-webkit-progress-bar { background: transparent; }
.progress::-webkit-progress-value { background: var(--accent); }
.progress::-moz-progress-bar { background: var(--accent); }
.progress:indeterminate { background: var(--hatch); }

